function eventCard(e){return `<article class="event-card" data-event="${e.eventId}"><span class="event-icon" role="img" aria-label="${esc(c.noImage)}">◈</span><h3>${esc(e.officialTitle)}</h3>${schedule(e)}<p>${esc(c.eligibility)}: ${esc(eligibility(e.participation))}</p><p>${esc(c.details[e.detailKey])}</p><details><summary>${esc(c.detail)}</summary><p>${esc(c.rules)} · ${esc(c.details[e.detailKey])}</p>${e.targetAniimo===null?`<p>Prismana: ${esc(c.unknown)}</p>`:''}<p>${esc(c.rewards)}: ${e.rewards.length?e.rewards.map(id=>esc(rewardName(data.rewards.find(r=>r.rewardId===id)?.name))).join(' · '):esc(c.unknown)}</p>${['viewed','done','daily','phase'].map(t=>addButton(e.eventId,t,c[t])).join(' ')}</details>${source(e)}<small>${esc(c.published)}: ${e.publishedAt}<br>${esc(c.checked)}: ${esc(e.sourceCheckedAt)}</small></article>`;}
function events(){const rows=data.events.filter(e=>(e.officialTitle+' '+c.details[e.detailKey]).toLowerCase().includes(state.search.toLowerCase())&&(state.status==='all'||selectedServers().some(s=>eventStatus(e,s)===state.status)));const past=rows.filter(e=>selectedServers().every(s=>eventStatus(e,s)==='ENDED_BY_SCHEDULE'));const current=rows.filter(e=>!past.includes(e)).sort((a,b)=>Number(a.category==='permanent-feature')-Number(b.category==='permanent-feature'));
return `<section id="events"><h2>${esc(c.events)}</h2><div class="event-filters"><label>${esc(c.search)}<input type="search" data-state="search" value="${esc(state.search)}"></label>${select('status',c.status,Object.keys(c.statuses).filter(s=>['ANNOUNCED','UPCOMING','ACTIVE_CONFIRMED','ENDING_SOON','ENDED_BY_SCHEDULE','POSTPONED','CANCELLED','AWAITING_UPDATE_CONFIRMATION','NEEDS_RECHECK','UNKNOWN'].includes(s)).map(s=>[s,c.statuses[s]]))}</div><p class="event-count" aria-live="polite">${rows.length}</p><div class="event-grid">${current.map(eventCard).join('')||`<p class="event-empty">${esc(c.noResults)}</p>`}</div><details><summary>${esc(c.history)} (${past.length})</summary><div class="event-grid">${past.slice(0,historyLimit).map(eventCard).join('')}</div>${past.length>historyLimit?`<button data-action="more">+4</button>`:''}</details></section>`;}
function rewards(){let rows=data.rewards.filter(r=>(state.rewardType==='all'||r.type===state.rewardType)&&(state.rewardEvent==='all'||r.eventId===state.rewardEvent));const statuses=r=>selectedServers().map(s=>rewardStatus(r,data.events.find(e=>e.eventId===r.eventId),s,checked(r.eventId,'reward:'+r.rewardId)));rows=rows.filter(r=>(state.rewardStatus==='all'||statuses(r).includes(state.rewardStatus))&&(state.rewardTime==='all'||selectedServers().some(s=>{const end=r.claimEndAt;return end&&Date.parse(end)>Date.now()&&Date.parse(end)-Date.now()<=3*86400000;})));
return `<section id="rewards"><h2>${esc(c.rewards)}</h2><div class="event-filters">${select('rewardType',c.rewardType,[...new Set(data.rewards.map(r=>r.type))].map(t=>[t,rewardName(t)]))}${select('rewardEvent',c.event,data.events.map(e=>[e.eventId,e.officialTitle]))}${select('rewardStatus',c.status,['UPCOMING','AVAILABLE','CLAIMABLE','CLAIMED_BY_USER','EXPIRED_BY_SCHEDULE','UNKNOWN'].map(s=>[s,c.statuses[s]]))}${select('rewardTime',c.time,[['soon',c.soon]])}</div><div class="event-grid">${rows.map(r=>`<article class="event-card" data-reward="${esc(r.rewardId)}"><span class="event-icon" role="img" aria-label="${esc(c.noImage)}">✦</span><h3>${esc(rewardName(r.name))}${r.quantity!==null?' × '+r.quantity:''}</h3><p>${esc(name(r.eventId))}</p>${[...new Set(statuses(r))].map(badge).join('')}<p>${esc(c.eligibility)}: ${esc(eligibility(r.eligibility))}</p><p>${esc(c.time)}: ${time(r.claimStartAt)} → ${time(r.claimEndAt)}</p><p>${esc(c.claimed)}</p>${addButton(r.eventId,'reward:'+r.rewardId,c.reward)}<p>${source(r)}</p></article>`).join('')||`<p class="event-empty">${esc(c.noResults)}</p>`}</div></section>`;}
function codes(){const official=data.codes.records.filter(r=>r.officialEvidence),thirdParty=data.codes.records.filter(r=>!r.officialEvidence);return `<section id="codes"><h2>${esc(c.codes)}</h2>${official.length?'':`<p>${esc(c.noOfficial)}</p>`}<p>${esc(c.stale)} ${esc(c.notRedeemed)}</p>${[[c.officialCodes,official],[c.thirdPartyCodes,thirdParty]].filter(([,rows])=>rows.length).map(([label,rows])=>`<h3>${esc(label)}</h3><div class="event-grid">${rows.map(r=>`<article class="event-card"><h3><code>${esc(r.code)}</code></h3>${badge(codeStatus(r))}<p>${esc(r.reportedReward)}</p><p>${esc(c.server)}: ${esc(c.unknown)} · ${esc(c.end)}: ${time(r.expiryAt)}</p><p><a href="${esc(r.sourceUrl)}" rel="nofollow noopener" target="_blank">${esc(r.sourceLabel||(r.officialEvidence?c.source:'PC Gamer'))}</a> · ${esc(c.sourcePublished)}: ${r.sourcePublishedAt}</p><p>${esc(c.published)}: ${time(r.codePublishedAt)}</p><p>${esc(c.checked)}: ${esc(r.recheckAttemptAt)}<br>${esc(c.sourceUpdated)}: ${r.sourceModifiedAt||r.sourceContentDate}</p><button data-copy="${esc(r.code)}">${esc(c.copy)}</button> ${addButton('code:'+r.code,'codeTried',c.codeTried)}</article>`).join('')}</div>`).join('')}<p class="event-copy-status" role="status"></p></section>`;}
function updates(){return `<section id="updates"><h2>${esc(c.updates)}</h2><div class="event-grid">${data.updates.map(u=>`<article class="event-card"><h3>${esc(u.officialTitle)}</h3>${badge(u.status)}${maintenanceStatus(u)!==u.status?badge(maintenanceStatus(u)):''}<p>${esc(c.published)}: ${u.publishedAt} · ${esc(c.version)}: ${esc(u.version||c.unknown)}</p>${u.maintenance?`<h4>${esc(c.maintenance)}</h4>${schedule({serverSchedules:u.maintenance,status:'ANNOUNCED',activationGate:'nov12-update'})}`:''}<p>${esc(c.details[u.summaryKey])}</p><p><a href="${config.prefix}/map/">Crescent Bay · Region Explorer →</a></p>${source(u)}<small>${esc(c.checked)}: ${esc(u.sourceCheckedAt)}</small></article>`).join('')}</div></section>`;}
function checklist(){const rows=store.data.records.filter(r=>(state.checkEvent==='all'||r.eventId===state.checkEvent)&&(state.checkStatus==='all'||r.checked===(state.checkStatus==='completed'))&&(!state.checkDate||r.checkedAt?.startsWith(state.checkDate)));return `<section id="checklist"><h2>${esc(c.checklist)}</h2><p>${esc(c.privacy)} ${esc(c.claimed)}</p><div class="event-filters">${select('checkEvent',c.event,[...new Set(store.data.records.map(r=>r.eventId))].map(id=>[id,name(id)]))}${select('checkStatus',c.status,[['remaining',c.remaining],['completed',c.completed]])}<label>${esc(c.date)}<input type="date" data-state="checkDate" value="${state.checkDate}"></label><button data-action="export">${esc(c.export)}</button></div><p>${esc(c.remaining)}: ${store.data.records.filter(r=>!r.checked).length} · ${esc(c.completed)}: ${store.data.records.filter(r=>r.checked).length}</p>${rows.map(r=>`<div class="event-check-row"><label><input type="checkbox" data-toggle="${esc(r.eventId)}" data-task="${esc(r.taskId)}"${r.checked?' checked':''}>${esc(name(r.eventId))} · ${esc(r.taskId.startsWith('reward:')?c.reward+' · '+rewardName(data.rewards.find(x=>x.rewardId===r.taskId.slice(7))?.name||c.unknown+' ('+r.taskId.slice(7)+')'):c[r.taskId]||r.taskId)}</label><button data-remove="${esc(r.eventId)}" data-task="${esc(r.taskId)}">${esc(c.remove)}</button>${r.checkedAt?`<small>${esc(r.checkedAt)}</small>`:''}</div>`).join('')||`<p class="event-empty">${esc(c.noResults)}</p>`}</section>`;}
function storageMessage(){const n=$('.event-storage');n.textContent=store.persistent?c.saved:c.session;n.dataset.session=String(!store.persistent);}
function render(){const mode=root.dataset.mode;$('.event-loaded').innerHTML=(mode==='events'?events()+rewards():mode==='codes'?codes():updates())+checklist();$('[data-filter=server]').value=store.data.server;storageMessage();}
function write(d){store.write(d);render();}
root.addEventListener('input',e=>{const k=e.target.dataset.state;if(!k||e.target.tagName==='SELECT')return;state[k]=e.target.value;const start=e.target.selectionStart;render();const next=root.querySelector(`[data-state="${k}"]`);next.focus();if(start!==null&&next.type==='search')next.setSelectionRange(start,start);});
root.addEventListener('change',e=>{if(!data)return;if(e.target.dataset.filter==='server'){write({...store.data,server:e.target.value});return;}if(e.target.dataset.state){state[e.target.dataset.state]=e.target.value;render();}if(e.target.dataset.toggle){const id=e.target.dataset.toggle,t=e.target.dataset.task;write({...store.data,records:store.data.records.map(r=>r.eventId===id&&r.taskId===t?{...r,checked:e.target.checked,checkedAt:new Date().toISOString()}:r)});}});
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!data)return;const d=b.dataset,id=d.add||d.remove,t=d.task;if(d.add){if(!store.data.records.some(r=>r.eventId===id&&r.taskId===t))write({...store.data,records:[...store.data.records,{eventId:id,taskId:t,checked:false,checkedAt:null}]});else document.getElementById('checklist').scrollIntoView();}if(d.remove)write({...store.data,records:store.data.records.filter(r=>!(r.eventId===id&&r.taskId===t))});if(d.copy){try{await navigator.clipboard.writeText(d.copy);$('.event-copy-status').textContent=c.copied;}catch{$('.event-copy-status').textContent=c.copyFailed;}}if(d.action==='export'){const blob=new Blob([JSON.stringify(store.data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aniimogg-checklist.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(d.action==='clear'){for(const k in state)state[k]=['search','checkDate'].includes(k)?'':'all';render();}if(d.action==='more'){historyLimit+=4;render();}});
